template <typename Char, typename... T>
struct formatter<tuple_join_view<Char, T...>, Char> {
 private:
  // A formatter for each element of the tuple with the parsed format specs.
  std::tuple<formatter<typename std::decay<T>::type, Char>...>
      element_formatters_;

  // Parses the format specs into the formatter of the element at index N.
  template <typename ParseContext, size_t N>
  FMT_CONSTEXPR auto parse_element_specs(ParseContext& ctx,
                                         const Char* begin) -> const Char* {
    basic_string_view<Char> specs(begin,
                                  detail::to_unsigned(ctx.end() - begin));
    ParseContext element_ctx(specs);
    return std::get<N>(element_formatters_).parse(element_ctx);
  }

  template <typename ParseContext>
  FMT_CONSTEXPR auto do_parse(ParseContext& ctx, detail::index_sequence<>)
      -> decltype(ctx.begin()) {
    // There are no elements to apply the specs to but they still need to be
    // consumed.
    auto begin = ctx.begin();
    auto end = ctx.end();
    while (begin != end && *begin != '}') {
      if (*begin == '{') {
        // Skip a nested replacement field, e.g. a dynamic width or precision.
        while (begin != end && *begin != '}') ++begin;
        if (begin != end) ++begin;
      } else {
        ++begin;
      }
    }
    return begin;
  }

  template <typename ParseContext, size_t... N>
  FMT_CONSTEXPR auto do_parse(ParseContext& ctx, detail::index_sequence<N...>)
      -> decltype(ctx.begin()) {
    auto begin = ctx.begin();
    auto end = begin;
    // Parse the format specs once for every element to make sure that they
    // are valid for all of them and to apply them to each element.
    const int _[] = {0, (end = parse_element_specs<N>(ctx, begin), 0)...};
    (void)_;
    return end;
  }

  template <typename FormatContext>
  auto format_args(const tuple_join_view<Char, T...>&, FormatContext& ctx) ->
      typename FormatContext::iterator {
    return ctx.out();
  }

  template <typename FormatContext, typename Arg, typename... Args>
  auto format_args(const tuple_join_view<Char, T...>& value, FormatContext& ctx,
                   const Arg& arg, const Args&... args) ->
      typename FormatContext::iterator {
    auto out = ctx.out();
    constexpr size_t index = sizeof...(T) - sizeof...(Args) - 1;
    if (index > 0) {
      auto sep_data = value.sep.data();
      out = detail::copy_str<Char>(sep_data, sep_data + value.sep.size(), out);
      ctx.advance_to(out);
    }
    out = std::get<index>(element_formatters_).format(arg, ctx);
    if (sizeof...(Args) > 0) {
      ctx.advance_to(out);
      return format_args(value, ctx, args...);
    }
    return out;
  }

 public:
  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    return do_parse(ctx, detail::make_index_sequence<sizeof...(T)>{});
  }

  template <typename FormatContext>
  auto format(const tuple_join_view<Char, T...>& value, FormatContext& ctx) ->
      typename FormatContext::iterator {
    return format(value, ctx, detail::make_index_sequence<sizeof...(T)>{});
  }

 private:
  template <typename FormatContext, size_t... N>
  auto format(const tuple_join_view<Char, T...>& value, FormatContext& ctx,
              detail::index_sequence<N...>) ->
      typename FormatContext::iterator {
    using std::get;
    return format_args(value, ctx, get<N>(value.tuple)...);
  }
};

